import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import classNames from 'classnames'
import {memo} from 'react'

import {useAppDispatch} from '../../../../../hooks/react-redux'
import useEventCallback from '../../../../../hooks/useEventCallback'
import {parameterGroups} from '../../Parameters.slice'

import styles from './ParametersGroupControls.module.css'

interface Props {
  className?: string
}

function ParametersGroupControls({className}: Props) {
  const dispatch = useAppDispatch()

  const onExpandAllClick = useEventCallback(() => {
    dispatch(parameterGroups.actions.expandAll())
  })
  const onCollapseAllClick = useEventCallback(() => {
    dispatch(parameterGroups.actions.collapseAll())
  })

  return (
    <ButtonSet
      className={classNames(className, styles.container)}
      data-test-parameters-group="controls"
    >
      <Button onClick={onExpandAllClick} data-test-control={'expand'}>
        {'Expand All'}
      </Button>
      <Button onClick={onCollapseAllClick} data-test-control={'collapse'}>
        {'Collapse All'}
      </Button>
    </ButtonSet>
  )
}

export default memo(ParametersGroupControls)
