import {Suspense} from 'react'
import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer} from 'react-relay'

import {useSyncedQueryParam} from '../../../../hooks/routes'
import {useBuildData} from '../../../../hooks/useEntity'
import type {BuildId} from '../../../../types'
import {BuildPageTabNamesEnum} from '../../../../types'
import {UserProperties} from '../../../../utils/userProperties'
import ClassicUITabAdapter from '../../../common/ClassicUITabAdapter/ClassicUITabAdapter'
import ModeSwitch, {Mode} from '../../../common/ModeSwitch/ModeSwitch'
import ParametersGroupControls from '../../../packages/Parameters/components/GroupControls/ParametersGroupControls'

import {buildParametersTabParam} from './BuildParameters.consts'
import {BuildParametersKindTab} from './BuildParameters.types'
import {useQueryBuildSubscriptionForParameters} from './hooks/useQueryBuildSubscriptionForParameters'
import type {BuildParametersEntryPoint} from './Parameters/BuildParameters.entryPoint'

import styles from './BuildParametersTab.module.css'

export type NestedEntryPoints = {parameters?: typeof BuildParametersEntryPoint}
interface Props {
  buildId: BuildId
}

export default function BuildParametersTab({
  entryPoints,
  props,
}: EntryPointProps<{}, NestedEntryPoints, Props, {}>) {
  const {buildId} = props

  useQueryBuildSubscriptionForParameters(buildId)

  const buildState = useBuildData({buildId}, build => build?.state)

  const [mode, setMode] = useSyncedQueryParam({
    param: buildParametersTabParam,
    userProperty: UserProperties.BUILD_PARAMETERS_TAB,
    skip: true,
  })

  return (
    <ModeSwitch
      userProperty={UserProperties.BUILD_PARAMETERS_TAB}
      preserveParams={({buildTab}) => ({buildTab})}
      param={buildParametersTabParam}
      customItems={
        mode === BuildParametersKindTab.PARAMETERS && (
          <ParametersGroupControls className={styles.controls} />
        )
      }
    >
      <Mode mode={BuildParametersKindTab.PARAMETERS} label="Parameters">
        {entryPoints.parameters && (
          <Suspense>
            <EntryPointContainer entryPointReference={entryPoints.parameters} props={{buildId}} />
          </Suspense>
        )}
      </Mode>
      <Mode
        mode={BuildParametersKindTab.STATISTICS}
        isDisabled={buildState === 'queued'}
        isForbidden={buildState === 'queued'}
        label="Statistic Values"
      >
        <ClassicUITabAdapter
          tabId={BuildPageTabNamesEnum.buildParameters}
          title={''}
          buildId={buildId}
          statistics
          onURLChange={url => {
            if (!url.includes('buildParametersTab=statistics')) {
              setMode(BuildParametersKindTab.PARAMETERS)
              return true
            }
            return false
          }}
        />
      </Mode>
    </ModeSwitch>
  )
}
export type BuildParametersTabComponent = typeof BuildParametersTab
